  line-height: 1;
  position: relative;
  transition: 
    color 0.4s cubic-bezier(0.32, 0.72, 0, 1),
    text-shadow 0.3s ease,
    filter 0.4s ease;  


  filter: 
    grayscale(100%) 
    brightness(0%) 
    contrast(1000%);  
}


.blackbox-mask:hover,
.blackbox-mask.active {
